#include <iomanip>
#include <iostream>

class Scoreboard {
public:
    explicit Scoreboard(int n) : count_(n), scores_(new double[n]()) {}

    ~Scoreboard() {
        delete[] scores_;
        std::cout << "released " << count_ << " scores\n";
    }

    Scoreboard(const Scoreboard&) = delete;
    Scoreboard& operator=(const Scoreboard&) = delete;

    void set(int i, double value) {
        scores_[i] = value;
    }

    double average() const {
        double total = 0.0;
        for (int i = 0; i < count_; ++i) {
            total += scores_[i];
        }
        return total / count_;
    }

private:
    int count_;
    double* scores_;
};

void report() {
    Scoreboard board(4);
    board.set(0, 88.5);
    board.set(1, 92.0);
    board.set(2, 79.5);
    board.set(3, 95.0);
    std::cout << "average " << board.average() << '\n';
}

int main() {
    std::cout << std::fixed << std::setprecision(2);
    report();
    std::cout << "back in main\n";
    return 0;
}

steps.body:
A `static` data member belongs to the class, not to any one object. There is exactly one copy, shared by every object, and it exists even when no objects do. It does not add to `sizeof` an object.

```cpp
class Connection {
public:
    static int openCount() {
        return openCount_;
    }
private:
    inline static int openCount_ = 0; // C++17
};
std::cout << Connection::openCount() << '\n';  // 0
```

C++17's `inline static` lets you initialize the member inside the class. Older code needs a separate line outside the class: `int Connection::openCount_ = 0;`.

A **static member function** has no `this` object, so it can use static members but not ordinary ones, because there is no object to read them from. Call it through the class name: `Connection::openCount()`.

Increment a static counter in the constructor and decrement it in the destructor, and it always holds the number of live objects. Delete the copy operations too: a compiler-made copy would skip your constructor, so the count would drift.

example.code:
#include <iostream>
#include <string>

class Connection {
public:
    explicit Connection(const std::string& host) : host_(host) {
        ++openCount_;
        std::cout << "connect " << host_ << '\n';
    }

    ~Connection() {
        --openCount_;
        std::cout << "disconnect " << host_ << '\n';
    }

    Connection(const Connection&) = delete;
    Connection& operator=(const Connection&) = delete;

    static int openCount() {
        return openCount_;
    }

private:
    std::string host_;
    inline static int openCount_ = 0;
};

int main() {
    std::cout << "open: " << Connection::openCount() << '\n';
    Connection db("db");
    {
        Connection cache("cache");
        Connection api("api");
        std::cout << "open: " << Connection::openCount() << '\n';
    }
    std::cout << "open: " << Connection::openCount() << '\n';
    return 0;
}

