#include <iostream>
#include <string>

class Ticket {
public:
    explicit Ticket(const std::string& holder) : id_(nextId_++), holder_(holder) {
        ++active_;
    }

    ~Ticket() {
        --active_;
    }

    Ticket(const Ticket&) = delete;
    Ticket& operator=(const Ticket&) = delete;

    static int issued() {
        return nextId_ - 1;
    }

    static int active() {
        return active_;
    }

    void print() const {
        std::cout << "ticket " << id_ << ": " << holder_ << '\n';
    }

private:
    int id_;
    std::string holder_;
    inline static int nextId_ = 1;
    inline static int active_ = 0;
};

int main() {
    std::cout << "issued: " << Ticket::issued() << ", active: " << Ticket::active() << '\n';
    const Ticket ana("Ana");
    {
        const Ticket ben("Ben");
        const Ticket cy("Cy");
        ben.print();
        cy.print();
        std::cout << "issued: " << Ticket::issued() << ", active: " << Ticket::active() << '\n';
    }
    ana.print();
    std::cout << "issued: " << Ticket::issued() << ", active: " << Ticket::active() << '\n';
    return 0;
}
